package cn.mop.persistence;

import cn.mop.domain.*;
import cn.mop.domain.ticketnote.*;
import cn.mop.domain.ticketnote.InternalTicketNoteRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Real V10/runtime-role notes over clearly synthetic report parents. No external provider or state transition. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresInternalTicketNoteIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresInternalTicketNoteRepository notes;static String engineer,viewer,admin,tadmin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);notes=new PostgresInternalTicketNoteRepository(pool,platform);engineer=actor("msp");viewer=actor("viewer");admin=actor("padmin");tadmin=actor("tadmin");assertEquals(List.of(),notes.readinessProblems());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor){return new Access(actor,TENANT,platform.membership(actor,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static String ticket(){String key=UUID.randomUUID().toString();var report=new CustomerReport("INTERNAL-NOTE-TEST-"+key,"虚构内部备注测试父登记","网络不通","individual","虚构联系人","+00 000","normal",null,List.of());var registered=(CustomerReportRegistration)platform.idempotent(viewer,TENANT,"POST /integration/internal-note-parent",key,"a".repeat(64),()->{var value=platform.registerCustomerReport(TENANT,viewer,report);platform.audit(viewer,TENANT,"integration.internal_note_parent.create","ticket",value.ticketId(),"SUCCEEDED","SYNTHETIC_ONLY",key);return value;});return registered.ticketId();}
    static long version(String ticket){return ((Number)platform.ticket(TENANT,engineer,ticket).orElseThrow().get("version")).longValue();}
    static Object command(PostgresPlatformRepository p,Access a,String route,String key,String hash,Supplier<Object> action){return p.idempotent(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),action);}
    static Entry create(String ticket,String actor,String text){Access a=access(actor);return (Entry)command(platform,a,"POST /integration/internal-notes/"+ticket,UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,ticket,version(ticket),new InternalTicketNote(text)));}
    static long audits(String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid AND payload->>'action'='ticket.internal_note.create' AND payload->>'resource_id'=?")){s.setString(1,TENANT);s.setString(2,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    @Test void immutableRawNoteAndFingerprintRoundTripWithIndependentConnection()throws Exception{String parent=ticket();Entry note=create(parent,engineer,"  内部说明😀\n原文\t ");assertEquals(engineer,note.actorId());assertEquals(TENANT,note.tenantId());assertEquals(parent,note.ticketId());assertEquals(1,note.observedTicketVersion());assertEquals("  内部说明😀\n原文\t ",note.note().text());assertEquals(note,new PostgresInternalTicketNoteRepository(pool,new PostgresPlatformRepository(pool,mapper)).get(access(admin),parent,note.id()));assertEquals(1,audits(note.id()));}
    @Test void internalNotesNeverChangeParentOrAppearInCustomerProjection(){String parent=ticket();var internalBefore=platform.ticket(TENANT,engineer,parent).orElseThrow();var customerBefore=platform.ticket(TENANT,viewer,parent).orElseThrow();create(parent,engineer,"内部调查内容");create(parent,admin,"内部协作内容");assertEquals(internalBefore,platform.ticket(TENANT,engineer,parent).orElseThrow());assertEquals(customerBefore,platform.ticket(TENANT,viewer,parent).orElseThrow());assertEquals(2,notes.list(access(engineer),parent,10,null,null).size());}
    @Test void bothInternalRolesCanContributeButCustomersCannotReadOrWrite(){String parent=ticket();Entry engineerNote=create(parent,engineer,"工程师备注"),adminNote=create(parent,admin,"管理员备注");assertEquals(admin,notes.get(access(engineer),parent,adminNote.id()).actorId());assertEquals(engineer,notes.get(access(admin),parent,engineerNote.id()).actorId());for(String user:List.of(viewer,tadmin)){Access a=access(user);assertEquals(403,assertThrows(DomainException.class,()->notes.list(a,parent,10,null,null)).status);assertEquals(403,assertThrows(DomainException.class,()->notes.get(a,parent,engineerNote.id())).status);assertEquals(403,assertThrows(DomainException.class,()->command(platform,a,"POST /integration/customer-note",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,parent,1,new InternalTicketNote("forbidden")))).status);}}
    @Test void originalKeyReplayKeepsOriginalReceiptAfterLaterNoteWithoutDuplicateAudit()throws Exception{String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/note-replay/"+parent;Access a=access(engineer);Object first=command(platform,a,route,key,"a".repeat(64),()->notes.create(a,parent,1,new InternalTicketNote("first")));create(parent,admin,"later");Object replay=command(platform,a,route,key,"a".repeat(64),()->{throw new AssertionError("Replay must not execute");});assertEquals(json(first),json(replay));assertEquals(2,notes.list(a,parent,10,null,null).size());assertEquals(1,audits(((Entry)first).id()));assertEquals(409,assertThrows(DomainException.class,()->command(platform,a,route,key,"b".repeat(64),()->null)).status);}
    @Test void wrongParentVersionDoesNotWriteAndUnguardedTransactionCannotRun(){String parent=ticket();Access a=access(engineer);assertThrows(IllegalStateException.class,()->notes.create(a,parent,1,new InternalTicketNote("unguarded")));assertEquals(409,assertThrows(DomainException.class,()->command(platform,a,"POST /integration/note-conflict",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,parent,2,new InternalTicketNote("stale")))).status);assertTrue(notes.list(a,parent,10,null,null).isEmpty());}
    @Test void foreignParentAndWrongParentNoteAre404()throws SQLException{String parent=ticket(),other=ticket();Entry note=create(parent,engineer,"scope");Access a=access(engineer);assertEquals(404,assertThrows(DomainException.class,()->notes.get(a,other,note.id())).status);String foreign;try(var c=pool.getConnection();var s=c.prepareStatement("SELECT id::text FROM public.mop_ticket WHERE tenant_id=?::uuid LIMIT 1")){s.setString(1,OTHER);try(var r=s.executeQuery()){assertTrue(r.next());foreign=r.getString(1);}}assertEquals(404,assertThrows(DomainException.class,()->notes.list(a,foreign,10,null,null)).status);assertEquals(404,assertThrows(DomainException.class,()->command(platform,a,"POST /integration/foreign-note",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,foreign,1,new InternalTicketNote("foreign")))).status);}
    @Test void stalePermissionAndUnknownMembershipFailClosed(){String parent=ticket();Access a=access(engineer),stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->notes.list(stale,parent,10,null,null)).status);assertEquals(401,assertThrows(DomainException.class,()->notes.list(new Access(UUID.randomUUID().toString(),TENANT,1,"synthetic"),parent,10,null,null)).status);assertEquals(401,assertThrows(DomainException.class,()->command(platform,stale,"POST /integration/stale-note",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(stale,parent,1,new InternalTicketNote("stale")))).status);}
    @Test void downstreamFailureRollsBackNoteAuditAndReplayThenSameKeyCanSucceed()throws Exception{String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/rollback-note/"+parent;Access a=access(engineer);Entry[] attempted=new Entry[1];assertThrows(IllegalStateException.class,()->command(platform,a,route,key,"a".repeat(64),()->{attempted[0]=notes.create(a,parent,1,new InternalTicketNote("rollback"));throw new IllegalStateException("Synthetic downstream failure");}));assertTrue(notes.list(a,parent,10,null,null).isEmpty());assertEquals(0,audits(attempted[0].id()));Entry saved=(Entry)command(platform,a,route,key,"a".repeat(64),()->notes.create(a,parent,1,new InternalTicketNote("rollback")));assertEquals(1,audits(saved.id()));assertEquals(1,notes.list(a,parent,10,null,null).size());}
    @Test void concurrentSameKeyAcrossIndependentConnectionsCommitsExactlyOneNote()throws Exception{String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/concurrent-note/"+parent;Access a=access(engineer);ExecutorService executor=Executors.newFixedThreadPool(2);CountDownLatch ready=new CountDownLatch(2),start=new CountDownLatch(1);try{List<Future<Object>> pending=new ArrayList<>();for(int i=0;i<2;i++)pending.add(executor.submit(()->{var p=new PostgresPlatformRepository(pool,mapper);var n=new PostgresInternalTicketNoteRepository(pool,p);ready.countDown();start.await();return command(p,a,route,key,"a".repeat(64),()->n.create(a,parent,1,new InternalTicketNote("same original request")));}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();assertEquals(json(pending.get(0).get(15,TimeUnit.SECONDS)),json(pending.get(1).get(15,TimeUnit.SECONDS)));var all=notes.list(a,parent,10,null,null);assertEquals(1,all.size());assertEquals(1,audits(all.get(0).id()));}finally{executor.shutdownNow();}}
    @Test void independentConcurrentNotesRemainSeparateWithoutChangingObservedParentVersion()throws Exception{String parent=ticket();ExecutorService executor=Executors.newFixedThreadPool(2);try{var a=executor.submit(()->create(parent,engineer,"note-a"));var b=executor.submit(()->create(parent,admin,"note-b"));assertNotEquals(a.get(15,TimeUnit.SECONDS).id(),b.get(15,TimeUnit.SECONDS).id());assertEquals(1,version(parent));assertEquals(2,notes.list(access(engineer),parent,10,null,null).size());}finally{executor.shutdownNow();}}
    @Test void boundedCreationCursorHasNoDuplicatesAndRejectsMalformedBoundaries(){String parent=ticket();for(int i=0;i<4;i++)create(parent,engineer,"page-"+i);Access a=access(engineer);var first=notes.list(a,parent,2,null,null);Entry tail=first.get(1);var second=notes.list(a,parent,2,tail.createdAt(),tail.id());assertEquals(2,second.size());assertTrue(first.stream().noneMatch(x->second.stream().anyMatch(y->x.id().equals(y.id()))));assertEquals(400,assertThrows(DomainException.class,()->notes.list(a,parent,102,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->notes.list(a,parent,10,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->notes.list(a,parent,10,Instant.EPOCH.plusNanos(1),tail.id())).status);}
    @Test void maximumUnicodeNoteIsStoredWithoutLoss(){String parent=ticket();String text="😀".repeat(2000);Entry note=create(parent,engineer,text);assertEquals(text,notes.get(access(admin),parent,note.id()).note().text());assertEquals(new InternalTicketNote(text).sha256(),note.note().sha256());}
}
